    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'PHOTO-LIC', qty: 3 },
      { sku: 'FONT-LIC', qty: 2 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal % 1, 0);
  assert.equal(totals.total % 1, 0);
});
